import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user from session cookie (simplified)
app.use(async (req, res, next) => {
  const sessionId = req.cookies?.session_id;
  if (!sessionId) return res.status(401).json({ error: 'Unauthorized' });
  const result = await pool.query('SELECT user_id, role FROM sessions WHERE id = $1 AND expires_at > NOW()', [sessionId]);
  if (result.rows.length === 0) return res.status(401).json({ error: 'Session expired' });
  req.user = result.rows[0];
  next();
});

