// Health check endpoint (reads instance metadata for status)
app.get('/api/health', async (req, res) => {
  const dbOk = await pool.query('SELECT 1').then(() => true).catch(() => false);
  res.json({ status: 'ok', db: dbOk, uptime: process.uptime() });
});

// Fetch remote config (internal use)
app.get('/api/internal/config-refresh', async (req, res) => {
  if (req.headers['x-internal-token'] !== process.env.INTERNAL_TOKEN) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  // Fetches config from parameter store
  const configUrl = process.env.CONFIG_ENDPOINT || 'http://169.254.169.254/latest/meta-data/';
  const resp = await fetch(configUrl);
  const data = await resp.text();
  res.json({ config: data });
});

